const crypto = require('crypto');
const item = $input.item;
const headers = item.json.headers || {};
const provided = String(headers['x-istpetdev-review-token'] || headers['X-IstpetDev-Review-Token'] || '');
const expected = String($env.ISTPETDEV_WEBHOOK_SECRET || '');
let tokenValid = false;
if (provided && expected && provided.length === expected.length) {
  tokenValid = crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected));
}
const binary = item.binary || {};
const keys = Object.keys(binary);
const hasFile = keys.length === 1;
const authorized = tokenValid && hasFile;
const reason = !tokenValid ? 'token_mismatch' : (!hasFile ? 'missing_file' : null);
return { json: { authorized: authorized, reason: reason }, binary: hasFile ? { file: binary[keys[0]] } : {} };

const statusCode = Number($json.statusCode || 0);
let report = $json.body;
if (typeof report === 'string') { try { report = JSON.parse(report); } catch (error) { report = null; } }
if (!report || typeof report !== 'object' || Array.isArray(report)) {
  return { json: { valid: false, error: 'invalid_report', message: 'La API no devolvio un reporte de importacion legible.' } };
}
const feasibility = report.feasibility || {};
const entities = Array.isArray(report.entities) ? report.entities : [];
const issues = Array.isArray(report.issues) ? report.issues : [];
const verdicts = { Viable: 'Viable para ruteo', ViableWithLimitations: 'Viable con limitaciones', Inviable: 'Inviable para rutear el dataset completo' };
const importacion = {
  estado: String(report.status || 'Desconocido'),
  aplicado: Boolean(report.applied),
  errores: Number(report.errorCount || 0),
  advertencias: Number(report.warningCount || 0),
  revisadoEnSeco: Boolean(report.dryRun)
};
const balance = entities.map(function (entity) { return {
  entidad: String(entity.entity || ''),
  archivo: entity.file ? String(entity.file) : null,
  filasLeidas: Number(entity.rowsRead || 0),
  creadas: Number(entity.created || 0),
  actualizadas: Number(entity.updated || 0),
  omitidas: Number(entity.skipped || 0),
  duplicados: Number(entity.duplicates || 0)
}; });
const puntosSinCoordenadas = (feasibility.unroutablePoints || []).map(function (point) { return {
  codigo: String(point.code || ''),
  nombre: String(point.name || ''),
  fila: point.row === null || point.row === undefined ? null : Number(point.row)
}; });
const stockVsDemanda = (feasibility.stockShortages || []).map(function (shortage) { return {
  sku: String(shortage.sku || ''),
  nombre: String(shortage.name || ''),
  unidad: String(shortage.baseUnit || ''),
  demanda: Number(shortage.demanded || 0),
  disponible: Number(shortage.available || 0)
}; });
const bodegasSinFlota = (feasibility.warehousesWithoutFleet || []).map(function (warehouse) { return {
  codigo: String(warehouse.code || ''),
  nombre: String(warehouse.name || '')
}; });
const productosSinCapacidad = (feasibility.productsWithoutCapacity || []).map(function (product) { return {
  sku: String(product.sku || ''),
  nombre: String(product.name || ''),
  motivo: String(product.reason || '')
}; });
const accionesSeguras = [];
entities.forEach(function (entity) {
  const assumptions = entity.assumptions || {};
  Object.keys(assumptions).sort().forEach(function (key) {
    accionesSeguras.push('Supuesto automatico en ' + String(entity.entity || '') + ': ' + String(assumptions[key].note || key) + ' (' + Number(assumptions[key].rows || 0) + ' filas).');
  });
  if (Number(entity.duplicates || 0) > 0) {
    accionesSeguras.push('Duplicados consolidados en ' + String(entity.entity || '') + ': ' + Number(entity.duplicates) + '.');
  }
});
const accionesHumanas = issues.filter(function (issue) { return String(issue.severity || '') === 'Error'; }).map(function (issue) { return {
  archivo: issue.file ? String(issue.file) : null,
  fila: Number(issue.row || 0),
  campo: issue.field ? String(issue.field) : null,
  codigo: String(issue.code || ''),
  mensaje: String(issue.message || '')
}; });
puntosSinCoordenadas.forEach(function (point) {
  accionesHumanas.push({ archivo: 'service_points', fila: point.fila, campo: 'lat/lon', codigo: 'missing_coordinates',
    mensaje: 'El punto ' + point.codigo + ' (' + point.nombre + ') no tiene coordenadas; agregue lat/lon en la fuente.' });
});
stockVsDemanda.forEach(function (shortage) {
  accionesHumanas.push({ archivo: 'consumptions/stock', fila: null, campo: 'quantity', codigo: 'stock_shortage',
    mensaje: 'La demanda de ' + shortage.sku + ' (' + shortage.demanda + ') supera el stock fisico en bodegas (' + shortage.disponible + ').' });
});
bodegasSinFlota.forEach(function (warehouse) {
  accionesHumanas.push({ archivo: 'vehicles', fila: null, campo: 'depot_code', codigo: 'warehouse_without_fleet',
    mensaje: 'La bodega ' + warehouse.codigo + ' (' + warehouse.nombre + ') no tiene vehiculos activos con capacidad.' });
});
productosSinCapacidad.forEach(function (product) {
  accionesHumanas.push({ archivo: 'products', fila: null, campo: 'weight_per_unit/volume_per_unit', codigo: 'product_without_capacity',
    mensaje: 'El producto ' + product.sku + ' no tiene peso/volumen unitario; no se puede verificar la capacidad del camion.' });
});
const contadores = {
  puntosSinCoordenadas: puntosSinCoordenadas.length,
  stockVsDemanda: stockVsDemanda.length,
  bodegasSinFlota: bodegasSinFlota.length,
  productosSinCapacidad: productosSinCapacidad.length,
  accionesSeguras: accionesSeguras.length,
  accionesHumanas: accionesHumanas.length,
  errores: importacion.errores
};
const dictamen = {
  veredicto: verdicts[String(feasibility.verdict || '')] || 'Viable con limitaciones',
  importacion: importacion,
  contadores: contadores,
  balance: balance,
  puntosSinCoordenadas: puntosSinCoordenadas,
  stockVsDemanda: stockVsDemanda,
  bodegasSinFlota: bodegasSinFlota,
  productosSinCapacidad: productosSinCapacidad,
  accionesSeguras: accionesSeguras,
  accionesHumanas: accionesHumanas
};
return { json: { valid: statusCode === 200 || statusCode === 422, statusCode: statusCode, dictamen: dictamen, facts: JSON.stringify(dictamen) } };

function deterministicSummary(dictamen) {
  const partes = [dictamen.veredicto + '.'];
  const importacion = dictamen.importacion || {};
  const contadores = dictamen.contadores || {};
  if (Number(importacion.errores) > 0) {
    partes.push('La importacion quedo en estado ' + importacion.estado + ' con ' + Number(importacion.errores) + ' errores; corrijalos y repita la revision en seco.');
  } else {
    partes.push('Revision en seco ' + importacion.estado + ' sin errores.');
  }
  if (Number(contadores.puntosSinCoordenadas) > 0) partes.push(Number(contadores.puntosSinCoordenadas) + ' puntos sin coordenadas no seran ruteables.');
  if (Number(contadores.stockVsDemanda) > 0) partes.push('Hay deficit de stock en ' + Number(contadores.stockVsDemanda) + ' SKUs.');
  if (Number(contadores.bodegasSinFlota) > 0) partes.push(Number(contadores.bodegasSinFlota) + ' bodegas no tienen flota activa con capacidad.');
  if (Number(contadores.accionesHumanas) > 0) partes.push(Number(contadores.accionesHumanas) + ' correcciones requieren revision humana.');
  return partes.join(' ');
}
function summaryIsGrounded(summary, facts) {
  const text = String(summary);
  const numbers = text.match(/\d+(?:[.,]\d+)?/g) || [];
  const digest = String(facts).replace(/[^0-9.,]/g, ' ');
  return numbers.every(function (number) {
    if (digest.indexOf(number) >= 0) return true;
    const normalized = number.replace(',', '.');
    return digest.indexOf(normalized) >= 0;
  });
}
const analysis = (($('Analizar viabilidad').first() || {}).json) || {};
const dictamen = analysis.dictamen || null;
const input = $json || {};
const executionId = String($execution.id || '');
if (!dictamen) {
  return { json: {
    veredicto: 'Sin dictamen',
    resumen: analysis.message ? String(analysis.message) : 'No se pudo construir el dictamen de viabilidad; revise el reporte del importador.',
    dictamen: null,
    promptVersion: 'v1',
    n8nExecutionId: executionId,
    agentError: input.error ? String(input.error) : (analysis.error ? String(analysis.error) : 'dictamen_missing')
  } };
}
const facts = typeof analysis.facts === 'string' ? analysis.facts : JSON.stringify(dictamen);
let summary = deterministicSummary(dictamen);
let agentError = null;
let parsed = null;
try {
  let raw = typeof input.output === 'string' ? input.output.trim() : input.output;
  if (typeof raw === 'string' && raw.indexOf('```') === 0) {
    raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  }
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) { parsed = null; }
if (!parsed || typeof parsed.resumenEjecutivo !== 'string' || !parsed.resumenEjecutivo.trim()) {
  agentError = input.error ? String(input.error) : 'invalid_llm_output';
} else if (!summaryIsGrounded(parsed.resumenEjecutivo, facts)) {
  agentError = 'llm_numbers_not_grounded';
} else {
  summary = parsed.resumenEjecutivo.trim();
}
return { json: {
  veredicto: dictamen.veredicto,
  resumen: summary,
  dictamen: dictamen,
  promptVersion: 'v1',
  n8nExecutionId: executionId,
  agentError: agentError
} };
